<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { Check, Edit3, Fingerprint, Plus, RefreshCw, Trash2, X } from 'lucide-vue-next'
import { api, ApiError } from '@/api/client'
import type { ClientMatcher, ClientProfile } from '@/types'
import { useToast } from '@/composables/toast'

const profiles = ref<ClientProfile[]>([])
const loading = ref(true)
const error = ref('')
const dialogOpen = ref(false)
const saving = ref(false)
const editingID = ref<string | number | null>(null)
const form = ref<{ name: string; description: string; enabled: boolean; priority: number; matchers: ClientMatcher[] }>({ name: '', description: '', enabled: true, priority: 100, matchers: [] })
const toast = useToast()

async function load() { loading.value = true; error.value = ''; try { profiles.value = await api.listClientProfiles() } catch (requestError) { error.value = requestError instanceof ApiError ? requestError.message : '无法加载客户端规则' } finally { loading.value = false } }
function openCreate() { editingID.value = null; form.value = { name: '', description: '', enabled: true, priority: 100, matchers: [{ type: 'prefix', value: '' }] }; dialogOpen.value = true }
function openEdit(profile: ClientProfile) { editingID.value = profile.id; form.value = { name: profile.name, description: profile.description || '', enabled: profile.enabled, priority: profile.priority, matchers: profile.matchers.length ? profile.matchers.map((matcher) => ({ ...matcher })) : [{ type: 'prefix', value: '' }] }; dialogOpen.value = true }
function close() { if (!saving.value) dialogOpen.value = false }
function addMatcher() { form.value.matchers.push({ type: 'prefix', value: '' }) }
function removeMatcher(index: number) { form.value.matchers.splice(index, 1) }
async function save() { if (!form.value.name.trim() || !form.value.matchers.some((matcher) => matcher.value.trim())) { toast.show('请填写名称和至少一条匹配规则', { tone: 'error' }); return }; saving.value = true; const payload = { ...form.value, name: form.value.name.trim(), description: form.value.description.trim(), matchers: form.value.matchers.filter((matcher) => matcher.value.trim()).map((matcher) => ({ ...matcher, value: matcher.value.trim() })) }; try { const result = editingID.value == null ? await api.createClientProfile(payload) : await api.updateClientProfile(editingID.value, payload); if (editingID.value == null) profiles.value.push(result); else profiles.value = profiles.value.map((profile) => profile.id === editingID.value ? result : profile); dialogOpen.value = false; toast.show(editingID.value == null ? '客户端规则已创建' : '客户端规则已更新') } catch (requestError) { toast.show('保存失败', { detail: requestError instanceof ApiError ? requestError.message : '请稍后重试', tone: 'error' }) } finally { saving.value = false } }
async function remove(profile: ClientProfile) { if (!window.confirm(`确定删除“${profile.name}”吗？`)) return; try { await api.deleteClientProfile(profile.id); profiles.value = profiles.value.filter((item) => item.id !== profile.id); toast.show('规则已删除', { tone: 'info' }) } catch (requestError) { toast.show('删除失败', { detail: requestError instanceof ApiError ? requestError.message : '请稍后重试', tone: 'error' }) } }
onMounted(load)
</script>

<template>
  <section class="page-view"><div class="page-heading"><div><p class="eyebrow">CLIENT IDENTITY / MATCHING</p><h1>客户端规则</h1><p class="page-subtitle">通过 User-Agent 识别客户端，并决定是否进入审核范围。</p></div><div class="heading-actions"><button class="secondary-button" :disabled="loading" @click="load"><RefreshCw :size="16" :class="{ spin: loading }" />刷新</button><button class="primary-button" @click="openCreate"><Plus :size="16" />新建规则</button></div></div><div v-if="error" class="error-banner"><Fingerprint :size="18" />{{ error }}<button class="text-button" @click="load">重试</button></div><div class="client-rule-grid"><article v-for="profile in profiles" :key="profile.id" class="panel client-card"><div class="client-card-head"><div class="client-icon"><Fingerprint :size="19" /></div><div class="client-card-title"><h2>{{ profile.name }}</h2><span>优先级 {{ profile.priority }}</span></div><span class="status-pill" :class="profile.enabled ? 'status-on' : 'status-off'"><i />{{ profile.enabled ? '启用' : '停用' }}</span></div><p class="client-description">{{ profile.description || '未填写描述' }}</p><div class="matcher-list"><div v-for="matcher in profile.matchers" :key="`${matcher.type}-${matcher.value}`" class="matcher-chip"><span>{{ matcher.type === 'prefix' ? '前缀' : matcher.type === 'exact' ? '精确' : '正则' }}</span><code>{{ matcher.value }}</code></div><span v-if="!profile.matchers.length" class="muted">暂无匹配条件</span></div><div class="card-actions"><button class="text-button" @click="openEdit(profile)"><Edit3 :size="15" />编辑</button><button class="icon-button danger-button" title="删除规则" aria-label="删除规则" @click="remove(profile)"><Trash2 :size="16" /></button></div></article><div v-if="!loading && !profiles.length" class="empty-state panel"><Fingerprint :size="28" /><strong>还没有客户端规则</strong><span>未识别的客户端默认按宽松模式放行。</span><button class="secondary-button" @click="openCreate"><Plus :size="15" />添加规则</button></div></div><div v-if="dialogOpen" class="modal-scrim" @click.self="close"><form class="modal-card wide" @submit.prevent="save"><div class="modal-header"><div><p class="eyebrow">CLIENT PROFILE</p><h2>{{ editingID == null ? '新建客户端规则' : '编辑客户端规则' }}</h2></div><button type="button" class="icon-button" aria-label="关闭" @click="close"><X :size="18" /></button></div><div class="form-grid"><label class="field-label">规则名称<input v-model="form.name" placeholder="例如：内部 Codex CLI" /></label><label class="field-label">优先级<input v-model.number="form.priority" type="number" min="0" max="999999" /></label></div><label class="field-label">描述<textarea v-model="form.description" rows="2" placeholder="说明该客户端的来源与用途" /></label><label class="toggle-row"><input v-model="form.enabled" type="checkbox" /><span class="toggle-control" /><span><strong>启用此规则</strong><small>匹配后才会进入审核范围</small></span></label><div class="matcher-editor"><div class="section-label">匹配条件 <button type="button" class="text-button" @click="addMatcher"><Plus :size="14" />添加条件</button></div><div v-for="(matcher, index) in form.matchers" :key="index" class="matcher-edit-row"><select v-model="matcher.type"><option value="prefix">前缀匹配</option><option value="exact">精确匹配</option><option value="regex">正则匹配</option></select><input v-model="matcher.value" placeholder="例如：codex_cli_rs/" /><button type="button" class="icon-button danger-button" aria-label="删除条件" @click="removeMatcher(index)"><Trash2 :size="15" /></button></div></div><div class="modal-actions"><button type="button" class="secondary-button" @click="close">取消</button><button type="submit" class="primary-button" :disabled="saving"><Check :size="16" />{{ saving ? '保存中…' : '保存规则' }}</button></div></form></div></section>
</template>
